CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;


DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20250719184728_InitialCreate') THEN
    CREATE TABLE "Barbearias" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nome" character varying(100) NOT NULL,
        "Endereco" character varying(200) NOT NULL,
        "Telefone" character varying(20) NOT NULL,
        "Email" character varying(100) NOT NULL,
        "Logo" character varying(500),
        "CodigoConvite" character varying(10) NOT NULL,
        "DataCriacao" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Barbearias" PRIMARY KEY ("Id")
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20250719184728_InitialCreate') THEN
    CREATE TABLE "Usuarios" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "Nome" character varying(100) NOT NULL,
        "Email" character varying(100) NOT NULL,
        "SenhaHash" character varying(255) NOT NULL,
        "TipoUsuario" integer NOT NULL,
        "BarbeariaId" integer,
        "Foto" character varying(500),
        "Especialidades" character varying(500),
        "Descricao" character varying(1000),
        "DataCriacao" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_Usuarios" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Usuarios_Barbearias_BarbeariaId" FOREIGN KEY ("BarbeariaId") REFERENCES "Barbearias" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20250719184728_InitialCreate') THEN
    CREATE TABLE "HorariosDisponiveis" (
        "Id" integer GENERATED BY DEFAULT AS IDENTITY,
        "DataHora" timestamp with time zone NOT NULL,
        "BarbeiroId" integer NOT NULL,
        "EstaDisponivel" boolean NOT NULL,
        "DataCriacao" timestamp with time zone NOT NULL,
        CONSTRAINT "PK_HorariosDisponiveis" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_HorariosDisponiveis_Usuarios_BarbeiroId" FOREIGN KEY ("BarbeiroId") REFERENCES "Usuarios" ("Id") ON DELETE CASCADE
    );
    END IF;
END $EF$;

DO $EF$
