        "Observacoes" character varying(500),
        "Status" integer NOT NULL,
        "DataCriacao" timestamp with time zone NOT NULL,
        "DataAtualizacao" timestamp with time zone,
        "BarbeariaId" integer NOT NULL,
        "HorarioDisponivelId" integer,
        CONSTRAINT "PK_Agendamentos" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_Agendamentos_Barbearias_BarbeariaId" FOREIGN KEY ("BarbeariaId") REFERENCES "Barbearias" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Agendamentos_HorariosDisponiveis_HorarioDisponivelId" FOREIGN KEY ("HorarioDisponivelId") REFERENCES "HorariosDisponiveis" ("Id"),
        CONSTRAINT "FK_Agendamentos_Usuarios_BarbeiroId" FOREIGN KEY ("BarbeiroId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT,
        CONSTRAINT "FK_Agendamentos_Usuarios_ClienteId" FOREIGN KEY ("ClienteId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

